message:
Command `cd /workspace && bash build.sh 'set -ex
cd /gt/_work/src
cmake -S . -B /gt/build-msan -G Ninja -DCMAKE_C_COMPILER=clang -DCMAKE_CXX_COMPILER=clang++ -DBUILD_SHARED_LIBS=OFF -DLIBICAL_BUILD_DOCS=OFF -DLIBICAL_BUILD_EXAMPLES=OFF -DLIBICAL_GLIB=OFF -DLIBICAL_GOBJECT_INTROSPECTION=OFF -DLIBICAL_BUILD_TESTING=OFF -DLIBICAL_GLIB_BUILD_DOCS=OFF -DCMAKE_C_FLAGS="-fsanitize=memory -fsanitize-memory-track-origins=2 -O1 -g -fPIE -fno-omit-frame-pointer" -DCMAKE_EXE_LINKER_FLAGS="-fsanitize=memory -fsanitize-memory-track-origins=2 -pie" 
ninja -C /gt/build-msan -j2 icalvcard
cat > /gt/libicalvcard_fuzzer.c <<"EOF"
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include "libicalvcard/vcardparser.h"
#include "libicalvcard/vcardcomponent.h"
int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    char *str = (char *)malloc(Size + 1);
    if (!str) return 0;
    memcpy(str, Data, Size);
    str[Size] = 0;
    vcardcomponent *card = vcardparser_parse_string(str);
    if (card) vcardcomponent_free(card);
    free(str);
    return 0;
}
EOF
clang -fsanitize=fuzzer,memory -fsanitize-memory-track-origins=2 -O1 -g -fPIE -fno-omit-frame-pointer -I/gt/build-msan/src -I/gt/build-msan/src/libicalvcard -I/gt/_work/src/src -I/gt/_work/src/src/libicalvcard /gt/libicalvcard_fuzzer.c -o /gt/libicalvcard_fuzzer /gt/build-msan/lib/libicalvcard.a /gt/build-msan/lib/libical.a -lm -lpthread
ls -l /gt/libicalvcard_fuzzer
'` executed with exit code -1.

